from decimal import Decimal
from typing import Any


def _field(record: dict | None, name: str) -> Any:
    if record is None:
        return ""
    return record.get(name, "")


def _numeric(value: Any) -> Decimal:
    if value == "":
        return Decimal(0)
    return Decimal(str(value))


def _lookup(
    tables: dict | None,
    table_name: str,
    key_col: str,
    key_val: Any,
    out_col: str,
) -> Any:
    if tables is None:
        return ""

    for row in tables.get(table_name, []):
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get(key_col, "") == key_val:
            return row.get(out_col, "")
    return ""


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    errors: list[dict] = []

    def add(code: str, message: str) -> None:
        errors.append(
            {
                "code": code,
                "message": message,
                "severity": "BLOCK",
            }
        )

    old_record = None if event == "INSERT" else old

    if table == "ORD_HEADER":
        if event in ("INSERT", "UPDATE"):
            disc_pct = _numeric(_field(record, "DISC_PCT"))
            if not (disc_pct >= Decimal(0) and disc_pct <= Decimal(100)):
                add("E5001", "Discount out of range")

        if event == "UPDATE":
            disc_pct = _numeric(_field(record, "DISC_PCT"))
            role_id = _lookup(
                tables,
                "USR_MASTER",
                "USR_ID",
                _field(record, "OWNER_UID"),
                "ROLE_ID",
            )
            if disc_pct > Decimal(20) and role_id != "MGR" and role_id != "ADMIN":
                add(
                    "E5002",
                    "Discount over 20 percent requires manager role",
                )

        if event == "UPDATE":
            if (
                _field(old_record, "STAT_CD") == "I"
                and _field(record, "STAT_CD") != "I"
                and _field(record, "STAT_CD") != "X"
            ):
                add("E5003", "Invoiced order can only be cancelled")

    elif table == "ORD_LINE":
        if event in ("INSERT", "UPDATE"):
            if not (_numeric(_field(record, "QTY")) > Decimal(0)):
                add("E5004", "Quantity must be positive")

        if event == "INSERT":
            active_flg = _lookup(
                tables,
                "PROD_MASTER",
                "PROD_ID",
                _field(record, "PROD_ID"),
                "ACTIVE_FLG",
            )
            if active_flg != "Y":
                add("E5005", "Product not active")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
